import { existsSync, readdirSync, readFileSync, statSync } from 'node:fs';
import { join, relative } from 'node:path';
import { describe, expect, it } from 'vitest';

// The Claude Code plugin in plugin/ is generated by `pnpm bundle`; these catch a stale copy.
const repo = join(import.meta.dirname, '..', '..', '..');
const plugin = join(repo, 'plugin');
const read = (...parts: string[]) => readFileSync(join(...parts), 'utf8');
const json = (...parts: string[]) => JSON.parse(read(...parts)) as Record<string, unknown>;
const STALE = 'plugin/ is out of date: run "pnpm bundle"';

describe('plugin', () => {
  it('ships the current skill', () => {
    const src = join(repo, '.claude', 'skills', 'minecraft-builder');
    const out = join(plugin, 'skills', 'minecraft-builder');
    expect(readdirSync(out).sort(), STALE).toEqual(readdirSync(src).sort());
    for (const f of readdirSync(src)) expect(read(out, f), `${f}: ${STALE}`).toBe(read(src, f));
  });

  it('ships the current guides', () => {
    const src = join(repo, 'apps', 'server', 'guides');
    const out = join(plugin, 'server', 'guides');
    expect(readdirSync(out).sort(), STALE).toEqual(readdirSync(src).sort());
    for (const f of readdirSync(src)) expect(read(out, f), `${f}: ${STALE}`).toBe(read(src, f));
  });

  it('installs the runtime dependencies the bundle leaves external', () => {
    const root = json(repo, 'package.json');
    const runtime = json(plugin, 'package.json');
    const deps = (p: Record<string, unknown>) => Object.keys(p.dependencies as object).sort();
    expect(deps(runtime), STALE).toEqual(deps(root));
    const lock = json(plugin, 'package-lock.json') as { packages: Record<string, unknown> };
    expect((lock.packages[''] as Record<string, unknown>).dependencies).toEqual(
      runtime.dependencies,
    );
  });

  it('has the release version and a launcher', () => {
    const root = json(repo, 'package.json');
    expect(json(plugin, '.claude-plugin', 'plugin.json').version, STALE).toBe(root.version);
    expect(existsSync(join(plugin, 'server', 'server.mjs')), STALE).toBe(true);
    expect(existsSync(join(plugin, 'server', 'web', 'dist', 'index.html')), STALE).toBe(true);
  });

  // Claude Code spawns MCP servers with cross-spawn: the extensionless name runs the sh script on
  // macOS/Linux and resolves to start-server.cmd (PATHEXT) on Windows.
  it('launches the same way on macOS, Linux and Windows', () => {
    const { mcpServers } = json(plugin, '.mcp.json') as {
      mcpServers: Record<string, { command: string; args?: string[] }>;
    };
    expect(mcpServers).toEqual({
      vibeschem: { command: '${CLAUDE_PLUGIN_ROOT}/scripts/start-server', args: [] },
    });
    const sh = join(plugin, 'scripts', 'start-server');
    expect(read(sh).startsWith('#!/bin/sh\n')).toBe(true);
    expect(statSync(sh).mode & 0o111, 'start-server must be executable').not.toBe(0);
    expect(read(sh)).toContain('"$ROOT/scripts/launch.mjs"');

    const cmd = read(plugin, 'scripts', 'start-server.cmd');
    expect(
      cmd.split('\r\n').every((line) => !line.includes('\n')),
      'start-server.cmd needs CRLF',
    ).toBe(true);
    expect(cmd).toContain('"%ROOT%\\scripts\\launch.mjs" %*');
    expect(existsSync(join(plugin, 'scripts', 'launch.mjs'))).toBe(true);
  });
});

// What Anthropic's plugin directory blocks on (https://claude.com/docs/plugins/pre-submission-checklist).
describe('plugin directory listing', () => {
  const manifest = json(plugin, '.claude-plugin', 'plugin.json') as Record<string, string>;
  // Every file the directory would scan: the committed plugin, not what launch.mjs installs.
  const local = new Set(['node_modules', '.install.log', '.install-lock']);
  const files = readdirSync(plugin, { recursive: true, withFileTypes: true })
    .map((d) => relative(plugin, join(d.parentPath, d.name)))
    .filter((p) => !local.has(p.split(/[\\/]/)[0] as string));

  it('has a permanent, unreserved kebab-case name', () => {
    expect(manifest.name).toBe('vibeschem');
    expect(manifest.name).toMatch(/^[a-z0-9](?:[a-z0-9-]{0,62}[a-z0-9])?$/);
    const market = json(repo, '.claude-plugin', 'marketplace.json') as {
      plugins: { name: string }[];
    };
    expect(market.plugins.map((p) => p.name)).toEqual([manifest.name]);
  });

  it('has a README of at least 40 words outside code blocks', () => {
    const prose = read(plugin, 'README.md').replace(/```[\s\S]*?```/g, '');
    expect(prose.split(/\s+/).filter(Boolean).length).toBeGreaterThanOrEqual(40);
  });

  it('ships the license, the third-party notices and the icon', () => {
    expect(read(plugin, 'LICENSE'), STALE).toBe(read(repo, 'LICENSE'));
    const license = json(repo, 'package.json').license;
    expect(license).toBe('AGPL-3.0-only');
    expect(manifest.license).toBe(license);
    expect(json(plugin, 'package.json').license, STALE).toBe(license);
    expect(json(repo, 'mcpb', 'manifest.json').license).toBe(license);
    expect(read(plugin, 'THIRD_PARTY_NOTICES.md'), STALE).toContain('## three ');
    expect(manifest.icon).toBe('./icon.png');
    expect(readFileSync(join(plugin, 'icon.png')), STALE).toEqual(
      readFileSync(join(repo, 'mcpb', 'icon.png')),
    );
  });

  it('links its documentation, support and privacy policy over https', () => {
    for (const key of ['homepage', 'documentationUrl', 'supportUrl', 'privacyPolicyUrl']) {
      expect(manifest[key], key).toMatch(/^https:\/\//);
    }
    expect(existsSync(join(repo, 'PRIVACY.md'))).toBe(true);
  });

  it('only has files every app can install', () => {
    expect(
      existsSync(join(plugin, 'bin')),
      'a top-level bin/ stops claude.ai from installing it',
    ).toBe(false);
    const junk = /(^|[\\/])(\.DS_Store|Thumbs\.db|desktop\.ini|__MACOSX)$/i;
    expect(files.filter((p) => junk.test(p))).toEqual([]);
    expect(files.filter((p) => /[:<>"|?*]|[. ]$/.test(p))).toEqual([]);
    const lower = files.map((p) => p.toLowerCase());
    expect(lower.filter((p, i) => lower.indexOf(p) !== i)).toEqual([]);
  });

  it('has no .gitattributes that rewrites file contents', () => {
    for (const dir of [repo, plugin]) {
      const file = join(dir, '.gitattributes');
      if (existsSync(file)) {
        expect(read(file)).not.toMatch(
          /\b(filter|text|eol|ident|working-tree-encoding|export-\w+)\b/,
        );
      }
    }
  });
});

// The Claude Desktop extension (`pnpm mcpb`) packs plugin/server with mcpb/manifest.json.
describe('desktop extension manifest', () => {
  const manifest = json(repo, 'mcpb', 'manifest.json') as {
    version: string;
    server: { entry_point: string; mcp_config: unknown };
    tools: { name: string }[];
  };

  it('has the release version', () => {
    expect(manifest.version, 'mcpb/manifest.json: run "pnpm bundle"').toBe(
      json(repo, 'package.json').version,
    );
  });

  it("runs the bundled server with Claude Desktop's built-in Node", () => {
    expect(manifest.server.entry_point).toBe('server/server.mjs');
    expect(manifest.server.mcp_config).toEqual({
      command: 'node',
      args: ['${__dirname}/server/server.mjs', '--mcp'],
    });
  });

  it('lists exactly the tools the server registers', () => {
    const source = read(repo, 'apps', 'server', 'src', 'mcp', 'server.ts');
    const registered = [...source.matchAll(/registerTool\(\s*'([a-z_]+)'/g)].map((m) => m[1]);
    expect(registered.length).toBeGreaterThan(0);
    expect(manifest.tools.map((t) => t.name).sort()).toEqual(registered.sort());
  });
});
